class TrendFilter:
    def filter(self, trends: list) -> list:
        return [
            t for t in trends
            if (any(cat in t.lower() for cat in ALLOWED_CATEGORIES))
            and not any(bl in t.lower() for bl in BLOCKLIST)
        ]

